 import { gsap } from 'gsap';
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, color, mix, smoothstep, length, positionLocal } from 'three/tsl';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, CylinderGeometry, PlaneGeometry,
    DirectionalLight, PointLight, Box3, Vector3, Color, DoubleSide
  } = ctx.THREE;

  const root = new Group();
  root.name = 'watch-hero';

  const visual = config.intent?.visualSpec ?? config;
  const colors = visual.colors ?? {};
  const bg = colors.background ?? '#0b0b10';
  const surface = colors.surface ?? '#14141a';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const gradientStops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' }
  ];

  const timelines = [];
  const primitiveRefs = [];
  let loadedScene = null;
  let disposed = false;

  // --- Backdrop gradient plane ---
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  const v = uv().y;
  const c0 = color(gradientStops[0].hex);
  const c1 = color(gradientStops[1].hex);
  const c2 = color(gradientStops[2].hex);
  const grad = mix(
    mix(c0, c1, smoothstep(gradientStops[0].at, gradientStops[1].at, v)),
    c2,
    smoothstep(gradientStops[1].at, gradientStops[2].at, v)
  );
  backdropMat.colorNode = grad;
  backdropMat.transparent = true;
  backdropMat.opacity = 0;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // --- Key / rim accent lighting ---
  const keyLight = new DirectionalLight(paper, 1.2);
  keyLight.position.set(4, 5.5, 7);
  root.add(keyLight);

  const rimLight = new PointLight(accent, 0.8, 24);
  rimLight.position.set(-4, 2.5, 3.5);
  root.add(rimLight);

  // --- Plinth ---
  const plinthGeo = new CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new MeshPhysicalNodeMaterial({
    color: surface,
    roughness: 0.7,
    metalness: 0.3
  });
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.y = -1.225;
  plinth.castShadow = true;
  plinth.receiveShadow = true;
  root.add(plinth);

  // --- Contact shadow ---
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  const shadowMat = new MeshBasicNodeMaterial({ color: bg, side: DoubleSide });
  const pxy = vec2(positionLocal.x, positionLocal.y);
  const dist = length(pxy);
  const shadowAlpha = smoothstep(1.6, 0.85, dist).mul(0.55);
  shadowMat.opacityNode = shadowAlpha;
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.y = -1.38;
  root.add(shadowPlane);

  // --- Product pivot (rotates, hovers) ---
  const pivot = new Group();
  pivot.name = 'product-pivot';
  root.add(pivot);

  // --- Load watch GLB ---
  const meshUrl = config.meshUrl ?? visual.meshUrl;
  if (meshUrl) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      if (disposed) return;
      loadedScene = gltf.scene;

      const box = new Box3().setFromObject(loadedScene);
      const size = new Vector3();
      box.getSize(size);
      const height = size.y || 1;
      const s = 2.2 / height;
      loadedScene.scale.setScalar(s);

      loadedScene.updateMatrixWorld(true);
      const b2 = new Box3().setFromObject(loadedScene);
      loadedScene.position.y = -1.1 - b2.min.y;

      loadedScene.traverse((o) => {
        if (o.isMesh) {
          applyWatchMaterial(o);
          o.castShadow = true;
          o.receiveShadow = true;
        }
      });

      pivot.add(loadedScene);
    }).catch(() => {});
  }

  function applyWatchMaterial(mesh) {
    const orig = mesh.material;
    if (!orig) return;

    const params = {
      color: orig.color ? orig.color.clone() : new Color(surface),
      roughness: 0.52,
      metalness: 0.55,
      clearcoat: 0.2,
      clearcoatRoughness: 0.4,
      anisotropy: 0.8,
      anisotropyRotation: 0
    };

    if (orig.map) params.map = orig.map;
    if (orig.normalMap) params.normalMap = orig.normalMap;
    if (orig.roughnessMap) params.roughnessMap = orig.roughnessMap;
    if (orig.metalnessMap) params.metalnessMap = orig.metalnessMap;

    const pmat = new MeshPhysicalNodeMaterial(params);
    mesh.material = pmat;
    if (orig.dispose) orig.dispose();
  }

  // --- Text ---
  const textGroup = new Group();
  root.add(textGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const textYByRole = {
    headline: -1.5,
    body: -1.75,
    caption: -2.0
  };

  for (const item of items) {
    const role = item.role || 'body';
    const str = String(item.text ?? '');
    if (!str) continue;

    let fontSize = 0.13;
    let textColor = paper;
    if (role === 'headline') {
      fontSize = 0.34;
    } else if (role === 'body') {
      fontSize = 0.13;
    } else if (role === 'caption') {
      fontSize = 0.09;
      textColor = accent;
    }

    const t = ctx.fontAtlas.createText(str, {
      fontSize,
      color: textColor,
      align: 'center'
    });
    t.position.y = textYByRole[role] ?? -1.75;
    textGroup.add(t);
  }

  // --- Entrance animations ---
  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  tl.to(
    backdropMat,
    { opacity: 1, duration: 0.6, ease: 'power2.out' },
    0
  );
  tl.from(
    plinth.position,
    { y: plinth.position.y - 0.25, duration: 0.7, ease: 'power2.out' },
    0
  );
  tl.from(
    textGroup.position,
    { y: textGroup.position.y + 0.4, duration: 0.7, ease: 'power3.out' },
    0
  );
  tl.from(
    pivot.scale,
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.9, ease: 'power4.out' },
    0
  );
  tl.from(
    pivot.position,
    { y: -0.25, duration: 0.7, ease: 'power2.out' },
    0
  );

  timelines.push(tl);

  // --- Cinematic primitives ---
  for (const prim of config.cinematicPrimitives ?? []) {
    if (prim.name === 'orbit') {
      primitiveRefs.push(ctx.primitives['orbit'](pivot, prim.params));
    } else if (prim.name === 'depth-rotate') {
      primitiveRefs.push(ctx.primitives['depth-rotate'](pivot, prim.params));
    }
  }

  // --- Handlers / cleanup ---
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    disposed = true;

    timelines.forEach((t) => t.kill());
    primitiveRefs.forEach((r) => {
      if (r && typeof r.cleanup === 'function') r.cleanup();
    });

    if (loadedScene) {
      loadedScene.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) disposeMaterial(o.material);
      });
    }

    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) disposeMaterial(o.material);
    });
  };

  function disposeMaterial(mat) {
    if (Array.isArray(mat)) {
      mat.forEach(disposeMaterial);
    } else if (mat && typeof mat.dispose === 'function') {
      mat.dispose();
    }
  }

  return root;
}
